return function(p1) -- line: 2
    if typeof(p1) ~= "table" then
        return false
    end

    if next(p1) == nil then
        return true
    end

    if #p1 == 0 then
        return false
    end

    local n1 = 0
    local n2 = 0

    for v1 in pairs(p1) do
        if typeof(v1) ~= "number" or v1 % 1 ~= 0 or v1 < 1 then
            return false
        end

        n1 += 1
        n2 += v1
    end

    return n2 == n1 * (n1 + 1) / 2
end
